import json

with open('baseline-packages.json') as f: baseline = json.load(f)
with open('after-cpm-packages.json') as f: after = json.load(f)

def extract(data):
    result = {}
    for proj in data.get('projects', []):
        name = proj['path'].split('/')[-1]
        for fw in proj.get('frameworks', []):
            for pkg in fw.get('topLevelPackages', []):
                key = (name, fw['framework'], pkg['id'])
                result[key] = pkg.get('resolvedVersion', '?')
    return result

b = extract(baseline)
a = extract(after)

changes = []
unchanged = []
for key in sorted(set(list(b.keys()) + list(a.keys()))):
    bv = b.get(key, 'N/A')
    av = a.get(key, 'N/A')
    proj, fw, pkg = key
    if bv != av:
        changes.append((proj, fw, pkg, bv, av))
    else:
        unchanged.append((proj, fw, pkg, bv))

if changes:
    print('CHANGES:')
    print(f'{\"Project\":20s} {\"TFM\":10s} {\"Package\":50s} {\"Before\":12s} {\"After\":12s}')
    for c in changes:
        print(f'{c[0]:20s} {c[1]:10s} {c[2]:50s} {c[3]:12s} {c[4]:12s}')
    print()

print(f'UNCHANGED: {len(unchanged)} packages resolve identically to baseline')
